def subtotal(price, quantity):
  return price * quantity

def discount(amount):
  if amount >= 500:
    return amount * 0.10
  return 0

def shipping(amount):
  if amount >= 400:
    return 0
  return 20

def settle(price, quantity):
  amount = subtotal(price, quantity)
  saving = discount(amount)
  fee = shipping(amount - saving)
  return {"商品金额": amount, "优惠": saving, "运费": fee, "实付": amount - saving + fee}

print(settle(80, 8))

