def payable(amount, rate):
  amount = float(amount)
  rate = float(rate)
  if amount < 0 or not 0 <= rate <= 1:
    raise ValueError("金额或折扣率无效")
  return amount * (1 - rate)

rows = [("天猫", 640, 0.15), ("京东", 360, 0.10), ("天猫", 500, 0.20), ("抖音", "六百", 0.10), ("京东", 800, 1.20), ("抖音", -100, 0.05)]
totals = {}
failed = 0
for channel, amount, rate in rows:
  try:
    value = payable(amount, rate)
  except ValueError:
    failed += 1
    continue
  totals[channel] = totals.get(channel, 0) + value
for channel, total in totals.items():
  print(channel, f"{total:.2f}")
print("失败", failed)
